// Deterministic Rotation & Duplicate Guard
// Picks the least-frequently and least-recently posted active product

const items = $input.all();
let products = [];

if (items.length > 0 && items[0].json && (items[0].json.name || items[0].json.product_name)) {
  products = items.map(i => i.json);
} else {
  // Default fallback rotation catalog
  products = [
    {
      product_id: 'AP-RO-001',
      product_name: 'AquaPure Copper Pro RO+UV+UF+TDS Water Purifier',
      category: 'purifier',
      verified_benefit: 'Delivers immune-boosting active copper ions and crisp alkaline hydration.',
      product_image_url: 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80',
      posted_count: 0,
      last_posted_at: null
    },
    {
      product_id: 'AP-WD-002',
      product_name: 'AquaPure Bottom-Loading Ergonomic Water Dispenser',
      category: 'dispenser',
      verified_benefit: 'Effortless bottom loading bottle replacement protects your back.',
      product_image_url: 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?auto=format&fit=crop&w=800&q=80',
      posted_count: 0,
      last_posted_at: null
    },
    {
      product_id: 'AP-BP-001',
      product_name: 'AquaPure High-Torque 75 GPD RO Booster Pump 24V DC',
      category: 'pump',
      verified_benefit: 'Whisper-quiet diaphragm pressure delivers maximum RO membrane recovery.',
      product_image_url: 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80',
      posted_count: 0,
      last_posted_at: null
    }
  ];
}

// Sort deterministically: lowest posted_count first
products.sort((a, b) => {
  const countA = a.posted_count || 0;
  const countB = b.posted_count || 0;
  if (countA !== countB) return countA - countB;
  const timeA = a.last_posted_at ? new Date(a.last_posted_at).getTime() : 0;
  const timeB = b.last_posted_at ? new Date(b.last_posted_at).getTime() : 0;
  return timeA - timeB;
});

const selected = products[0];

return [{
  json: {
    productId: selected.product_id || selected.id,
    productName: selected.product_name || selected.name,
    category: selected.category,
    verifiedBenefit: selected.verified_benefit || selected.verifiedBenefit || 'Pure drinking water for healthy living.',
    imageUrl: selected.product_image_url || selected.imageUrl,
    postedCount: (selected.posted_count || selected.postedCount || 0) + 1,
    timestamp: new Date().toISOString()
  }
}];

