// Prepare final validated caption and image payload
const selectorData = $('deterministic-product-selector').item.json;
const llmResponse = $('generate-llm-caption').item.json;

let caption = '';
try {
  if (llmResponse && llmResponse.candidates && llmResponse.candidates[0].content.parts[0].text) {
    caption = llmResponse.candidates[0].content.parts[0].text.trim();
  } else {
    caption = `Pure health in every drop! 💧 Infuse your daily hydration with crisp, pure minerals. Experience certified 99.9% purification with the ${selectorData.productName}. Tap link in bio for free installation! #AquaPure #WaterPurifier #CleanWater #Hydration`;
  }
} catch (e) {
  caption = `Transform your home water with ${selectorData.productName}! 💧 ${selectorData.verifiedBenefit} Tap link in bio to explore. #AquaPure #PureWater`;
}

// Public CDN Image URL (fallback to high-res catalog CDN image if AI binary is empty)
const publicImageUrl = selectorData.imageUrl || 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80';

return [{
  json: {
    ...selectorData,
    finalCaption: caption,
    publicImageUrl: publicImageUrl
  }
}];
